/**
Given a string, return a duplicate of the string. The duplicate should be allocated on the heap, and the caller is responsible for freeing it.

@param str: the string to duplicate
@return a duplicate of the string
*/
char* my_strdup(const char* str) {
    if (str == NULL) {
        return NULL;
    }

    // Calculate the length of the string.
    size_t len = strlen(str);

    // Allocate memory for the duplicate string, including the null terminator.
    // We add 1 for the null terminator.
    char* duplicate = (char*)malloc(len + 1);

    // Check if memory allocation failed.
    if (duplicate == NULL) {
        return NULL; // Indicate failure to allocate memory.
    }

    // Copy the string content to the allocated memory.
    // strcpy is safe here because we've already allocated enough space
    // for the string and its null terminator.
    strcpy(duplicate, str);

    // Return the pointer to the newly allocated and duplicated string.
    return duplicate;
}
